// gateThrottler holds the copier's read worker in BlockWait until the test
// releases it: one chunk per token, or everything once opened. It is binary
// (no GradualThrottler), so the change feed's flush never sees it as load.
type gateThrottler struct {
	tokens   chan struct{}
	open     chan struct{}
	openOnce sync.Once
	waits    atomic.Int64 // BlockWait calls entered so far
}

var _ throttler.Throttler = (*gateThrottler)(nil)

func newGateThrottler() *gateThrottler {
	return &gateThrottler{tokens: make(chan struct{}, 1), open: make(chan struct{})}
}

func (g *gateThrottler) Open(context.Context) error      { return nil }
func (g *gateThrottler) Close() error                    { return nil }
func (g *gateThrottler) UpdateLag(context.Context) error { return nil }
func (g *gateThrottler) release()                        { g.openOnce.Do(func() { close(g.open) }) }

func (g *gateThrottler) IsThrottled() bool {
	select {
	case <-g.open:
		return false
	default:
		return true
	}
}

func (g *gateThrottler) BlockWait(ctx context.Context) {
	g.waits.Add(1)
	select {
	case <-g.open:
	case <-g.tokens:
	case <-ctx.Done():
	}
}

// TestSyncPreDispatchChangeThenAboveHighWatermark: a change reaches the
// target before the initial copy dispatches its first chunk (sync's periodic
// flush starts before the copy), and a second change to the same row arrives
// once the copy has started.
//
// Before the fix the second change was discarded as above the high watermark,
// and the copier's INSERT IGNORE skipped the row because the first change had
// already put it on the target. The target entered continuous sync serving the
// first image (UPDATE) or a row the source had deleted (DELETE) until the
// lockless checksum reached that chunk and recopied it.
func TestSyncPreDispatchChangeThenAboveHighWatermark(t *testing.T) {
	for _, secondIsDelete := range []bool{false, true} {
		name := "update"
		if secondIsDelete {
			name = "delete"
		}
		t.Run(name, func(t *testing.T) {
			runSyncPreDispatchScenario(t, secondIsDelete)
		})
	}
}

func runSyncPreDispatchScenario(t *testing.T, secondIsDelete bool) {
	const key = 16384 // the top of the key space; far above the first chunk
	srcDB, destDB := "sync_predisp_src", "sync_predisp_dest"
	cfg, err := mysql.ParseDSN(testutils.DSN())
	require.NoError(t, err)
	src := cfg.Clone()
	src.DBName = srcDB
	dest := cfg.Clone()
	dest.DBName = destDB

	testutils.RunSQL(t, "DROP DATABASE IF EXISTS "+srcDB)
	testutils.RunSQL(t, "CREATE DATABASE "+srcDB)
	testutils.RunSQL(t, "CREATE TABLE "+srcDB+".t1 (id INT NOT NULL AUTO_INCREMENT PRIMARY KEY, b INT NOT NULL)")
	testutils.RunSQL(t, "INSERT INTO "+srcDB+".t1 (b) VALUES (1)")
	for range 14 {
		testutils.RunSQL(t, "INSERT INTO "+srcDB+".t1 (b) SELECT 1 FROM "+srcDB+".t1")
	}
	testutils.RunSQL(t, "ANALYZE TABLE "+srcDB+".t1")
	testutils.RunSQL(t, "DROP DATABASE IF EXISTS "+destDB)
	testutils.RunSQL(t, "CREATE DATABASE "+destDB)
	t.Cleanup(func() {
		testutils.RunSQL(t, "DROP DATABASE IF EXISTS "+srcDB)
		testutils.RunSQL(t, "DROP DATABASE IF EXISTS "+destDB)
	})

	tgt, err := sql.Open("block-mysql", dest.FormatDSN())
	require.NoError(t, err)
	defer utils.CloseAndLog(tgt)
	// targetRow returns the row's b and whether it exists; ok is false if the
	// query failed (for example, the table is not created yet).
	targetRow := func() (b int, exists, ok bool) {
		ctx, cancel := context.WithTimeout(t.Context(), 5*time.Second)
		defer cancel()
		err := tgt.QueryRowContext(ctx, fmt.Sprintf("SELECT b FROM t1 WHERE id = %d", key)).Scan(&b)
		if err == sql.ErrNoRows {
			return 0, false, true
		}
		if err != nil {
			return 0, false, false
		}
		return b, true, true
	}

	gate := newGateThrottler()
	runner, err := NewRunner(&Sync{
		SourceDSN:     src.FormatDSN(),
		TargetDSN:     dest.FormatDSN(),
		Common:        flags.Common{Threads: 1, WriteThreads: 2, MaxConnections: 16, SkipAutoscaling: true}, // one read worker, so one token is one chunk
		Target:        &applier.Target{DB: tgt, Config: dest},
		FlushInterval: 50 * time.Millisecond,
	})
	require.NoError(t, err)
	fakeAurora(runner, 2, throttler.AuroraResult{Throttlers: []throttler.Throttler{gate}})
	h := startRunner(t, runner)
	defer gate.release()

	// The read worker is parked before its first chunker.Next(). The target
	// table exists and the periodic flush is running.
	h.eventually(func() bool { return gate.waits.Load() >= 1 }, 30*time.Second, "copier parks before its first chunk")

	// (1) The first change reaches the target ahead of the copier.
	testutils.RunSQL(t, fmt.Sprintf("UPDATE %s.t1 SET b = 99 WHERE id = %d", srcDB, key))
	h.eventually(func() bool {
		b, exists, ok := targetRow()
		return ok && exists && b == 99
	}, 30*time.Second, "the first change is flushed to the target")

	// (2) Let exactly one chunk through. The read worker is back in BlockWait
	// once it has dispatched and processed it.
	gate.tokens <- struct{}{}
	h.eventually(func() bool { return gate.waits.Load() >= 2 }, 30*time.Second, "copier dispatches its first chunk")

	// (3) The second change, with the key now above the high watermark. Wait
	// until the change feed has read it.
	if secondIsDelete {
		testutils.RunSQL(t, fmt.Sprintf("DELETE FROM %s.t1 WHERE id = %d", srcDB, key))
	} else {
		testutils.RunSQL(t, fmt.Sprintf("UPDATE %s.t1 SET b = 100 WHERE id = %d", srcDB, key))
	}
	ctx, cancel := context.WithTimeout(t.Context(), 30*time.Second)
	defer cancel()
	require.NoError(t, runner.replClient.BlockWait(ctx))

	// (4) Finish the copy and enter continuous sync.
	gate.release()
	h.awaitContinuous(60 * time.Second)

	// The copy must hand continuous sync a correct target. This read races
	// the lockless checksum, which starts with the continuous phase and would
	// repair the row once it reaches its chunk, so the check after
	// FirstCleanPass below is the one that cannot miss.
	requireTargetMatches := func(when string) {
		t.Helper()
		b, exists, ok := targetRow()
		require.True(t, ok)
		if secondIsDelete {
			require.False(t, exists, "%s: the row deleted on the source is still on the target", when)
			return
		}
		require.True(t, exists, when)
		require.Equal(t, 100, b, "%s: the target kept the first change's image", when)
	}
	requireTargetMatches("after the copy")

	// The lockless checksum must not have had to repair anything.
	h.await(runner.FirstCleanPass(), 60*time.Second, "FirstCleanPass")
	stats := h.awaitInitialVerification(60 * time.Second)
	requireTargetMatches("after the first clean pass")
	require.Zero(t, stats.MismatchesDetected,
		"the lockless checksum found (and repaired) a divergence the copy left behind: %+v", stats)
	h.stop()
}

package migration

import (
	"errors"
	"fmt"
	"testing"

	"github.com/block/spirit/pkg/copier"
	"github.com/block/spirit/pkg/dbconn"
	"github.com/block/spirit/pkg/status"
	"github.com/block/spirit/pkg/table"
	"github.com/block/spirit/pkg/testutils"
	"github.com/block/spirit/pkg/utils"
	"github.com/stretchr/testify/require"
)

// TestE2EPreDispatchChangeThenAboveHighWatermark steps a migration through a
// change that lands before the copier's first dispatch, followed by a second
// change to the same key once the copier has started.
//
// The first change reaches the new table ahead of the copier (setup enables
// the watermark optimization before any chunk is dispatched, and a key the
// copier has not reached is flushed immediately). Before the fix the second
// change was then discarded as above the high watermark, and the copier's
// INSERT IGNORE skipped the key because it was already there. The new table
// kept the first change's image (or, after a DELETE, a row the source no
// longer has) and only the pre-cutover checksum repaired it. This test checks
// the new table before the checksum runs.
func TestE2EPreDispatchChangeThenAboveHighWatermark(t *testing.T) {
	for _, secondIsDelete := range []bool{false, true} {
		name := "update"
		if secondIsDelete {
			name = "delete"
		}
		t.Run(name, func(t *testing.T) {
			t.Parallel()
			tbl := "predisp_mig_upd"
			if secondIsDelete {
				tbl = "predisp_mig_del"
			}
			testutils.NewTestTable(t, tbl, fmt.Sprintf(`CREATE TABLE %s (
				id INT NOT NULL AUTO_INCREMENT PRIMARY KEY,
				b INT NOT NULL DEFAULT 0)`, tbl))
			testutils.RunSQL(t, fmt.Sprintf("INSERT INTO %s (b) VALUES (1)", tbl))
			for range 14 {
				testutils.RunSQL(t, fmt.Sprintf("INSERT INTO %s (b) SELECT 1 FROM %s", tbl, tbl))
			}
			testutils.RunSQL(t, "ANALYZE TABLE "+tbl)
			const key = 16384 // the top of the key space

			m := NewTestRunner(t, tbl, "ENGINE=InnoDB")
			defer utils.CloseAndLog(m)
			m.dbConfig = dbconn.NewDBConfig()
			m.status.Begin()
			var err error
			m.db, err = dbconn.New(testutils.DSN(), m.dbConfig)
			require.NoError(t, err)
			defer utils.CloseAndLog(m.db)
			m.changes[0].table = table.NewTableInfo(m.db, m.migration.Database, m.changes[0].stmt.Table)
			require.NoError(t, m.changes[0].table.SetInfo(t.Context()))
			// setup enables the watermark optimization before any chunk is
			// dispatched, exactly as Run does.
			require.NoError(t, m.setup(t.Context()))
			m.status.Set(status.CopyRows)

			// (1) The first change, before the copier dispatches anything.
			// The flush writes it to the new table ahead of the copier.
			testutils.RunSQL(t, fmt.Sprintf("UPDATE %s SET b = 99 WHERE id = %d", tbl, key))
			require.NoError(t, m.replClient.BlockWait(t.Context()))
			require.NoError(t, m.replClient.Flush(t.Context()))
			newTbl := m.changes[0].newTable.QuotedTableName
			var b int
			require.NoError(t, m.db.QueryRowContext(t.Context(),
				fmt.Sprintf("SELECT b FROM %s WHERE id = %d", newTbl, key)).Scan(&b))
			require.Equal(t, 99, b)

			ccopier, ok := m.copier.(copier.ChunkCopier)
			require.True(t, ok)

			// (2) The copier copies its first chunk, far below key.
			chunk, err := m.copyChunker.Next()
			require.NoError(t, err)
			require.NoError(t, ccopier.CopyChunk(t.Context(), chunk))

			// (3) The second change to the same key, now above the high
			// watermark.
			if secondIsDelete {
				testutils.RunSQL(t, fmt.Sprintf("DELETE FROM %s WHERE id = %d", tbl, key))
			} else {
				testutils.RunSQL(t, fmt.Sprintf("UPDATE %s SET b = 100 WHERE id = %d", tbl, key))
			}
			require.NoError(t, m.replClient.BlockWait(t.Context()))

			// (4) The copier finishes; every change is flushed.
			for {
				chunk, err := m.copyChunker.Next()
				if errors.Is(err, table.ErrTableIsRead) {
					break
				}
				require.NoError(t, err)
				require.NoError(t, ccopier.CopyChunk(t.Context(), chunk))
			}
			require.NoError(t, m.replClient.Flush(t.Context()))

			// The new table must already match, before any checksum runs.
			var n int
			require.NoError(t, m.db.QueryRowContext(t.Context(),
				fmt.Sprintf("SELECT COUNT(*) FROM %s WHERE id = %d", newTbl, key)).Scan(&n))
			if secondIsDelete {
				require.Equal(t, 0, n, "the row deleted on the source is still in the new table")
			} else {
				require.Equal(t, 1, n)
				require.NoError(t, m.db.QueryRowContext(t.Context(),
					fmt.Sprintf("SELECT b FROM %s WHERE id = %d", newTbl, key)).Scan(&b))
				require.Equal(t, 100, b, "the new table kept the first change's image")
			}

			m.status.Set(status.ApplyChangeset)
			m.status.Set(status.Checksum)
			require.NoError(t, m.checksum(t.Context()))
		})
	}
}

package throttler

import (
	"context"
	"sync"
	"sync/atomic"
	"testing"
	"time"

	"github.com/stretchr/testify/require"
)

func TestMonitorCloseCancelsAndJoins(t *testing.T) {
	// Drive the same lifecycle through each public Close method. Hold the
	// monitor after cancellation to prove Close waits for query teardown.
	replica := &Replica{}
	threads := &AuroraThreads{}
	latency := &CommitLatency{}
	for _, tc := range []struct {
		name      string
		loop      *monitorLoop
		throttler Throttler
	}{
		{"replica", &replica.poller, replica},
		{"threads", &threads.poller, threads},
		{"latency", &latency.poller, latency},
	} {
		t.Run(tc.name, func(t *testing.T) {
			cancelled, release, closed := make(chan struct{}), make(chan struct{}), make(chan struct{})
			ctx, cancel := context.WithCancel(t.Context())
			t.Cleanup(func() {
				cancel()
				close(release)
				tc.loop.close()
				<-closed
			})
			require.NoError(t, tc.loop.start(ctx, func(ctx context.Context) {
				<-ctx.Done()
				close(cancelled)
				<-release
			}))
			go func() {
				defer close(closed)
				_ = tc.throttler.Close()
			}()
			select {
			case <-cancelled:
			case <-time.After(5 * time.Second):
				t.Fatal("Close did not cancel the monitor")
			}
			select {
			case <-closed:
				t.Fatal("Close returned before the monitor exited")
			default:
			}
			release <- struct{}{}
			select {
			case <-closed:
			case <-time.After(5 * time.Second):
				t.Fatal("Close did not join the monitor")
			}
			require.NoError(t, tc.throttler.Close())
		})
	}
}

func TestMonitorCloseBeforeStart(t *testing.T) {
	var loop monitorLoop
	loop.close()
	require.ErrorIs(t, loop.start(t.Context(), func(context.Context) { t.Error("closed monitor started") }), errMonitorClosed)
	require.Nil(t, loop.done)
}

func TestMonitorConcurrentClose(t *testing.T) {
	var loop monitorLoop
	require.NoError(t, loop.start(t.Context(), func(ctx context.Context) { <-ctx.Done() }))
	var wg sync.WaitGroup
	for range 10 {
		wg.Go(loop.close)
	}
	wg.Wait()
	select {
	case <-loop.done:
	default:
		t.Fatal("Close returned before monitor exited")
	}
}

func TestClosedThrottlerCannotReopen(t *testing.T) {
	for _, throttler := range []Throttler{&Replica{}, &AuroraThreads{}, &CommitLatency{}} {
		require.NoError(t, throttler.Close())
		require.ErrorIs(t, throttler.Open(t.Context()), errMonitorClosed)
	}
}

func TestMonitorStartIsIdempotent(t *testing.T) {
	var loop monitorLoop
	var calls atomic.Int32
	started := make(chan struct{})
	ctx, cancel := context.WithCancel(t.Context())
	defer cancel()
	defer loop.close()
	require.NoError(t, loop.start(ctx, func(ctx context.Context) {
		calls.Add(1)
		close(started)
		<-ctx.Done()
	}))
	select {
	case <-started:
	case <-time.After(5 * time.Second):
		t.Fatal("monitor did not start")
	}
	originalDone := loop.done
	require.NoError(t, loop.start(ctx, func(ctx context.Context) {
		calls.Add(1)
		<-ctx.Done()
	}))
	require.Equal(t, originalDone, loop.done, "a repeated start must keep the original monitor")
	loop.close()
	require.Equal(t, int32(1), calls.Load())
}

package change

import (
	"context"
	"database/sql"
	"errors"
	"fmt"
	"testing"
	"time"

	mysql2 "github.com/block/mysql"
	"github.com/block/spirit/pkg/applier"
	"github.com/block/spirit/pkg/copier"
	"github.com/block/spirit/pkg/dbconn"
	"github.com/block/spirit/pkg/table"
	"github.com/block/spirit/pkg/testutils"
	"github.com/block/spirit/pkg/utils"
	"github.com/stretchr/testify/require"
)

// preDispatchClient is what the pre-dispatch tests need from both clients.
type preDispatchClient interface {
	Source
	Close()
	flush(ctx context.Context, underLock bool, locks []*dbconn.TableLock) error
}

// preDispatchTiming says when the first change reaches the target relative to
// the copier's first dispatch.
type preDispatchTiming string

const (
	// The first change is still buffered when the second arrives; the flush
	// after the first dispatch applies it (KeyNotYetDispatched).
	firstStillBuffered preDispatchTiming = "first-still-buffered"
	// The first change is flushed before the copier dispatches anything.
	firstFlushedBeforeDispatch preDispatchTiming = "first-flushed-before-dispatch"
	// The first change is flushed before the watermark optimization is
	// enabled. This is the order pkg/datasync uses: its periodic flush
	// starts before SetWatermarkOptimization(true).
	firstFlushedBeforeOptimization preDispatchTiming = "first-flushed-before-optimization"
)

// TestPreDispatchChangeThenAboveHighWatermark covers a change to a key that
// reaches the target before the copier dispatches a chunk covering it,
// followed by a second change to the same key after the copier has dispatched
// its first chunk.
//
// Before the fix the second change was discarded as above the high
// watermark, on the assumption that the copier would copy the row's latest
// state. It could not: the copier writes with INSERT IGNORE, and the first
// change had already put the key on the target. The target kept the first
// image (UPDATE), or a row the source no longer has (DELETE), with no change
// left buffered and the flushed position past both transactions.
//
// Every case runs on both chunkers (optimistic and composite), with and
// without the table.BufferedKeyNoter capability, and with both clients.
func TestPreDispatchChangeThenAboveHighWatermark(t *testing.T) {
	clients := map[string]func(t *testing.T, db *sql.DB, appl applier.Applier) preDispatchClient{
		"binlog": func(t *testing.T, db *sql.DB, appl applier.Applier) preDispatchClient {
			cfg, err := mysql2.ParseDSN(testutils.DSN())
			require.NoError(t, err)
			return NewBinlogClient(db, cfg.Addr, cfg.User, cfg.Passwd, appl, NewClientDefaultConfig()).(*binlogClient)
		},
		"gtid": func(t *testing.T, db *sql.DB, appl applier.Applier) preDispatchClient {
			skipUnlessGTIDEnabled(t)
			cfg, err := mysql2.ParseDSN(testutils.DSN())
			require.NoError(t, err)
			return NewGTIDClient(db, cfg.Addr, cfg.User, cfg.Passwd, appl, NewClientDefaultConfig()).(*gtidClient)
		},
	}
	timings := []preDispatchTiming{firstStillBuffered, firstFlushedBeforeDispatch, firstFlushedBeforeOptimization}
	for clientName, newClient := range clients {
		// An AUTO_INCREMENT key selects the optimistic chunker; any other key
		// the composite chunker.
		for _, chunkerType := range []string{"optimistic", "composite"} {
			for _, noterKind := range []string{"with-noter", "without-noter"} {
				for _, timing := range timings {
					for _, secondIsDelete := range []bool{false, true} {
						op := "update"
						if secondIsDelete {
							op = "delete"
						}
						c := preDispatchCase{
							timing:         timing,
							secondIsDelete: secondIsDelete,
							hideNoter:      noterKind == "without-noter",
							composite:      chunkerType == "composite",
						}
						t.Run(fmt.Sprintf("%s/%s/%s/%s/%s", clientName, chunkerType, noterKind, timing, op), func(t *testing.T) {
							runPreDispatchScenario(t, newClient, c)
						})
					}
				}
			}
		}
	}
}

// preDispatchCase is one combination of TestPreDispatchChangeThenAboveHighWatermark.
type preDispatchCase struct {
	timing         preDispatchTiming
	secondIsDelete bool
	// hideNoter gives the subscription a chunker without
	// table.BufferedKeyNoter: it must then never discard a change as above
	// the high watermark, and the target must still converge.
	hideNoter bool
	// composite uses a key without AUTO_INCREMENT, so the copy runs on the
	// composite chunker instead of the optimistic one.
	composite bool
}

// hiddenNoterChunker exposes only table.MappedChunker, hiding the wrapped
// chunker's optional table.BufferedKeyNoter capability. It stands in for an
// out-of-tree chunker that predates that interface.
type hiddenNoterChunker struct {
	table.MappedChunker
}

// subscriptionOf returns the bufferedMap a pre-dispatch test client created
// for schema.tbl.
func subscriptionOf(t *testing.T, client preDispatchClient, schema, tbl string) *bufferedMap {
	t.Helper()
	var subs *subscriptionRegistry
	switch c := client.(type) {
	case *binlogClient:
		subs = c.subs
	case *gtidClient:
		subs = c.subs
	default:
		t.Fatalf("unexpected client type %T", client)
	}
	sub, ok := subs.Get(encodeSchemaTable(schema, tbl))
	require.True(t, ok)
	buffered, ok := sub.(*bufferedMap)
	require.True(t, ok)
	return buffered
}

// runPreDispatchScenario runs the sequence described on
// TestPreDispatchChangeThenAboveHighWatermark for one preDispatchCase.
func runPreDispatchScenario(t *testing.T, newClient func(*testing.T, *sql.DB, applier.Applier) preDispatchClient, c preDispatchCase) {
	timing, secondIsDelete, hideNoter := c.timing, c.secondIsDelete, c.hideNoter
	db, err := dbconn.New(testutils.DSN(), dbconn.NewDBConfig())
	require.NoError(t, err)
	defer utils.CloseAndLog(db)

	testutils.RunSQL(t, "DROP TABLE IF EXISTS predisp_src, predisp_dst")
	autoInc := "auto_increment"
	if c.composite {
		autoInc = ""
	}
	testutils.RunSQL(t, fmt.Sprintf("CREATE TABLE predisp_src (a INT NOT NULL %s, b INT, PRIMARY KEY (a))", autoInc))
	testutils.RunSQL(t, fmt.Sprintf("CREATE TABLE predisp_dst (a INT NOT NULL %s, b INT, PRIMARY KEY (a))", autoInc))
	testutils.RunSQL(t, "INSERT INTO predisp_src (a,b) VALUES (1, 1)")
	for n := 1; n < 16384; n *= 2 { // a = 1..16384
		testutils.RunSQL(t, fmt.Sprintf("INSERT INTO predisp_src (a,b) SELECT a + %d, 1 FROM predisp_src", n))
	}
	testutils.RunSQL(t, "ANALYZE TABLE predisp_src")
	t.Cleanup(func() { testutils.RunSQL(t, "DROP TABLE IF EXISTS predisp_src, predisp_dst") })
	const key = 16384 // the top of the key space; far above the first chunk

	src := table.NewTableInfo(db, "test", "predisp_src")
	require.NoError(t, src.SetInfo(t.Context()))
	dst := table.NewTableInfo(db, "test", "predisp_dst")
	require.NoError(t, dst.SetInfo(t.Context()))

	appl := applier.NewSingleTargetForTest(t, db)
	// CopyChunk starts the applier's workers and leaves them running.
	defer func() { require.NoError(t, appl.Stop()) }()
	client := newClient(t, db, appl)

	chunker, err := table.NewChunker(src, table.ChunkerConfig{NewTable: dst, TargetChunkTime: time.Second})
	require.NoError(t, err)
	wantType := "Optimistic"
	if c.composite {
		wantType = "Composite"
	}
	require.Contains(t, fmt.Sprintf("%T", chunker), wantType)
	require.NoError(t, chunker.Open())
	subChunker := chunker
	if hideNoter {
		subChunker = hiddenNoterChunker{chunker}
		_, ok := subChunker.(table.BufferedKeyNoter)
		require.False(t, ok)
	}
	require.NoError(t, client.AddSubscription(src, dst, subChunker))
	require.NoError(t, client.Start(t.Context()))
	defer client.Close()
	sub := subscriptionOf(t, client, "test", "predisp_src")
	require.Equal(t, hideNoter, sub.keyNoter == nil)

	if timing != firstFlushedBeforeOptimization {
		require.NoError(t, client.SetWatermarkOptimization(t.Context(), true))
	}

	// (1) The first change, before the copier dispatches anything.
	testutils.RunSQL(t, fmt.Sprintf("UPDATE predisp_src SET b = 99 WHERE a = %d", key))
	require.NoError(t, client.BlockWait(t.Context()))
	require.Equal(t, 1, client.GetDeltaLen(), "the first change must be buffered")
	if timing != firstStillBuffered {
		require.NoError(t, client.flush(t.Context(), false, nil))
		require.Equal(t, 0, client.GetDeltaLen())
		var b int
		require.NoError(t, db.QueryRowContext(t.Context(), fmt.Sprintf("SELECT b FROM predisp_dst WHERE a = %d", key)).Scan(&b))
		require.Equal(t, 99, b, "the first change is on the target ahead of the copier")
	}
	if timing == firstFlushedBeforeOptimization {
		require.NoError(t, client.SetWatermarkOptimization(t.Context(), true))
	}

	cpCfg := copier.NewCopierDefaultConfig()
	cpCfg.Applier = appl
	cpAny, err := copier.NewCopier(chunker, cpCfg)
	require.NoError(t, err)
	cp, ok := cpAny.(copier.ChunkCopier)
	require.True(t, ok)

	// (2) The copier dispatches and copies its first chunk, far below key.
	chunk, err := chunker.Next()
	require.NoError(t, err)
	require.NoError(t, cp.CopyChunk(t.Context(), chunk))
	require.True(t, chunker.KeyNotYetDispatched(key))
	if hideNoter {
		// Nothing told the chunker about the first change, so it would
		// discard the second one. The subscription must not ask it.
		require.True(t, chunker.KeyAboveHighWatermark(key))
	}

	// (3) The second change to the same key. Its key is above the high
	// watermark; it must still reach the target.
	if secondIsDelete {
		testutils.RunSQL(t, fmt.Sprintf("DELETE FROM predisp_src WHERE a = %d", key))
	} else {
		testutils.RunSQL(t, fmt.Sprintf("UPDATE predisp_src SET b = 100 WHERE a = %d", key))
	}
	require.NoError(t, client.BlockWait(t.Context()))
	require.Zero(t, sub.keysDroppedAbove.Load(), "the second change was discarded as above the high watermark")

	// (4) A periodic flush, then the copier finishes the table.
	require.NoError(t, client.flush(t.Context(), false, nil))
	for {
		chunk, err := chunker.Next()
		if errors.Is(err, table.ErrTableIsRead) {
			break
		}
		require.NoError(t, err)
		require.NoError(t, cp.CopyChunk(t.Context(), chunk))
	}
	require.NoError(t, client.flush(t.Context(), false, nil))
	require.Equal(t, 0, client.GetDeltaLen())

	var srcRows, dstRows, dstB int
	require.NoError(t, db.QueryRowContext(t.Context(), fmt.Sprintf("SELECT COUNT(*) FROM predisp_src WHERE a = %d", key)).Scan(&srcRows))
	require.NoError(t, db.QueryRowContext(t.Context(), fmt.Sprintf("SELECT COUNT(*) FROM predisp_dst WHERE a = %d", key)).Scan(&dstRows))
	if secondIsDelete {
		require.Equal(t, 0, srcRows)
		require.Equal(t, 0, dstRows, "the row deleted on the source is still on the target")
		return
	}
	require.Equal(t, 1, dstRows)
	require.NoError(t, db.QueryRowContext(t.Context(), fmt.Sprintf("SELECT b FROM predisp_dst WHERE a = %d", key)).Scan(&dstB))
	require.Equal(t, 100, dstB, "the target kept the first change's image")
}

package runtime

import (
	"context"
	"errors"
	"fmt"
	"testing"
	"time"

	"github.com/block/spirit/pkg/status"
	"github.com/stretchr/testify/require"
)

// fakeSleep records every backoff instead of sleeping.
type fakeSleep struct {
	sleeps []time.Duration
	// onSleep, when set, runs before the sleep returns; its error is the
	// sleep's result.
	onSleep func() error
}

func (f *fakeSleep) sleep(ctx context.Context, d time.Duration) error {
	f.sleeps = append(f.sleeps, d)
	if f.onSleep != nil {
		return f.onSleep()
	}
	return ctx.Err()
}

func retry(_ error) (CutoverVerdict, error) { return CutoverVerdictRetry, nil }

func TestRetryCutoverBackoffDoublesToTheCap(t *testing.T) {
	fs := &fakeSleep{}
	attempts := 0
	err := RetryCutover(t.Context(), CutoverRetry{Attempts: 10, Sleep: fs.sleep},
		func(_ context.Context, i int) error {
			require.Equal(t, attempts, i)
			attempts++
			return errors.New("lock wait timeout")
		}, retry, nil, nil)
	require.Error(t, err)
	require.Equal(t, 10, attempts)
	// No sleep before the first attempt nor after the last: one per gap.
	require.Equal(t, []time.Duration{
		100 * time.Millisecond,
		200 * time.Millisecond,
		400 * time.Millisecond,
		800 * time.Millisecond,
		1600 * time.Millisecond,
		3200 * time.Millisecond,
		6400 * time.Millisecond,
		10 * time.Second,
		10 * time.Second,
	}, fs.sleeps)
}

func TestRetryCutoverCustomBackoff(t *testing.T) {
	fs := &fakeSleep{}
	err := RetryCutover(t.Context(), CutoverRetry{
		Attempts: 4, InitialBackoff: time.Second, MaxBackoff: 3 * time.Second, Sleep: fs.sleep,
	}, func(context.Context, int) error { return errors.New("x") }, retry, nil, nil)
	require.Error(t, err)
	require.Equal(t, []time.Duration{time.Second, 2 * time.Second, 3 * time.Second}, fs.sleeps)
}

// TestRetryCutoverInitialBackoffIsCapped checks MaxBackoff caps the first
// delay too, including against the default cap.
func TestRetryCutoverInitialBackoffIsCapped(t *testing.T) {
	fs := &fakeSleep{}
	err := RetryCutover(t.Context(), CutoverRetry{Attempts: 3, InitialBackoff: time.Hour, Sleep: fs.sleep},
		func(context.Context, int) error { return errors.New("lock wait timeout") }, retry, nil, nil)
	require.Error(t, err)
	require.Equal(t, []time.Duration{CutoverMaxBackoff, CutoverMaxBackoff}, fs.sleeps)
}

func TestRetryCutoverJoinsAttemptErrors(t *testing.T) {
	fs := &fakeSleep{}
	errs := []error{errors.New("first"), errors.New("second"), errors.New("third")}
	err := RetryCutover(t.Context(), CutoverRetry{Attempts: 3, Sleep: fs.sleep},
		func(_ context.Context, i int) error { return errs[i] }, retry, nil, nil)
	joined, ok := err.(interface{ Unwrap() []error })
	require.True(t, ok, "a joined error (%T)", err)
	require.Len(t, joined.Unwrap(), 3, "one error per attempt")
	for i, want := range errs {
		require.ErrorIs(t, err, want)
		require.ErrorContains(t, err, fmt.Sprintf("attempt %d: %s", i+1, want))
	}
}

func TestRetryCutoverExhaustedCallback(t *testing.T) {
	fs := &fakeSleep{}
	attemptErr := errors.New("lock wait timeout")
	var gotHistory error
	err := RetryCutover(t.Context(), CutoverRetry{Attempts: 2, Sleep: fs.sleep},
		func(context.Context, int) error { return attemptErr }, retry, nil,
		func(history []error) error {
			gotHistory = errors.Join(history...)
			return errors.Join(append(history, status.ErrOwnershipAmbiguous)...)
		})
	require.ErrorIs(t, gotHistory, attemptErr)
	require.ErrorContains(t, gotHistory, "attempt 2: lock wait timeout")
	require.ErrorIs(t, err, status.ErrOwnershipAmbiguous)

	// exhausted can resolve the failure: the rename committed after all.
	err = RetryCutover(t.Context(), CutoverRetry{Attempts: 2, Sleep: fs.sleep},
		func(context.Context, int) error { return attemptErr }, retry, nil,
		func([]error) error { return nil })
	require.NoError(t, err)
}

func TestRetryCutoverSuccessShortCircuits(t *testing.T) {
	fs := &fakeSleep{}
	attempts := 0
	err := RetryCutover(t.Context(), CutoverRetry{Attempts: 5, Sleep: fs.sleep},
		func(context.Context, int) error {
			attempts++
			if attempts == 2 {
				return nil
			}
			return errors.New("transient")
		}, retry, nil, nil)
	require.NoError(t, err)
	require.Equal(t, 2, attempts)
	require.Len(t, fs.sleeps, 1)
}

func TestRetryCutoverStopVerdicts(t *testing.T) {
	fs := &fakeSleep{}
	attemptErr := errors.New("ambiguous rename")

	t.Run("succeeded", func(t *testing.T) {
		attempts := 0
		err := RetryCutover(t.Context(), CutoverRetry{Attempts: 5, Sleep: fs.sleep},
			func(context.Context, int) error { attempts++; return attemptErr },
			func(error) (CutoverVerdict, error) { return CutoverVerdictSucceeded, nil }, nil, nil)
		require.NoError(t, err)
		require.Equal(t, 1, attempts)
	})

	t.Run("failed", func(t *testing.T) {
		attempts := 0
		err := RetryCutover(t.Context(), CutoverRetry{Attempts: 5, Sleep: fs.sleep},
			func(context.Context, int) error { attempts++; return attemptErr },
			func(error) (CutoverVerdict, error) {
				return CutoverVerdictFailed, errors.Join(status.ErrDurableMutation,
					fmt.Errorf("%w: not retrying", status.ErrOwnershipAmbiguous))
			}, nil, nil)
		require.Equal(t, 1, attempts)
		require.ErrorIs(t, err, attemptErr)
		require.ErrorContains(t, err, "attempt 1: ambiguous rename")
		require.ErrorIs(t, err, status.ErrOwnershipAmbiguous)
		require.ErrorIs(t, err, status.ErrDurableMutation)
	})

	t.Run("failed without extra", func(t *testing.T) {
		err := RetryCutover(t.Context(), CutoverRetry{Attempts: 5, Sleep: fs.sleep},
			func(context.Context, int) error { return attemptErr },
			func(error) (CutoverVerdict, error) { return CutoverVerdictFailed, nil }, nil, nil)
		require.ErrorIs(t, err, attemptErr)
		require.Equal(t, "attempt 1: ambiguous rename", err.Error())
	})
}

// TestRetryCutoverStopSeesOnlyTheCurrentError checks that a marker an earlier
// attempt carried does not reach the classification of a later attempt.
func TestRetryCutoverStopSeesOnlyTheCurrentError(t *testing.T) {
	fs := &fakeSleep{}
	marker := errors.New("marker")
	var seen []error
	err := RetryCutover(t.Context(), CutoverRetry{Attempts: 3, Sleep: fs.sleep},
		func(_ context.Context, i int) error {
			if i == 0 {
				return fmt.Errorf("first: %w", marker)
			}
			return fmt.Errorf("plain %d", i)
		},
		func(err error) (CutoverVerdict, error) {
			seen = append(seen, err)
			return CutoverVerdictRetry, nil
		}, nil, nil)
	require.ErrorIs(t, err, marker, "the history keeps every attempt")
	require.Len(t, seen, 3)
	require.ErrorIs(t, seen[0], marker)
	for _, e := range seen[1:] {
		require.NotErrorIs(t, e, marker)
		require.NotContains(t, e.Error(), "attempt ")
	}
	require.Equal(t, "first: marker", seen[0].Error(), "stop gets the attempt's error unprefixed")
}

func TestRetryCutoverZeroAttemptsIsOne(t *testing.T) {
	for _, n := range []int{0, -1} {
		fs := &fakeSleep{}
		attempts := 0
		err := RetryCutover(t.Context(), CutoverRetry{Attempts: n, Sleep: fs.sleep},
			func(context.Context, int) error { attempts++; return errors.New("x") }, retry, nil, nil)
		require.Error(t, err)
		require.Equal(t, 1, attempts)
		require.Empty(t, fs.sleeps)
	}
}

func TestRetryCutoverCancelDuringBackoff(t *testing.T) {
	ctx, cancel := context.WithCancel(t.Context())
	defer cancel()
	fs := &fakeSleep{onSleep: func() error {
		cancel()
		return context.Canceled
	}}
	attemptErr := errors.New("lock wait timeout")
	attempts := 0
	var gotHistory error
	cancelCalls := 0
	err := RetryCutover(ctx, CutoverRetry{Attempts: 5, Sleep: fs.sleep},
		func(context.Context, int) error { attempts++; return attemptErr }, retry,
		func(history []error) error {
			cancelCalls++
			gotHistory = errors.Join(history...)
			return errors.Join(append(history, ctx.Err())...)
		}, func([]error) error {
			t.Fatal("exhausted must not run on cancel")
			return nil
		})
	require.Equal(t, 1, attempts, "no attempt after the cancel")
	require.Equal(t, 1, cancelCalls)
	require.ErrorIs(t, gotHistory, attemptErr)
	require.ErrorIs(t, err, context.Canceled)
	require.ErrorContains(t, err, "attempt 1: lock wait timeout")
}

func TestRetryCutoverCancelBeforeFirstAttempt(t *testing.T) {
	ctx, cancel := context.WithCancel(t.Context())
	cancel()
	attempts := 0
	err := RetryCutover(ctx, CutoverRetry{Attempts: 3},
		func(context.Context, int) error { attempts++; return nil }, retry, nil, nil)
	require.ErrorIs(t, err, context.Canceled)
	require.Zero(t, attempts)
}

// TestRetryCutoverDefaultCancel checks the default onCancel joins the history
// with ctx's error, using the real, ctx-aware sleep.
func TestRetryCutoverDefaultCancel(t *testing.T) {
	ctx, cancel := context.WithCancel(t.Context())
	defer cancel()
	attemptErr := errors.New("lock wait timeout")
	start := time.Now()
	time.AfterFunc(50*time.Millisecond, cancel)
	err := RetryCutover(ctx, CutoverRetry{Attempts: 2, InitialBackoff: time.Hour},
		func(context.Context, int) error { return attemptErr }, retry, nil, nil)
	require.Less(t, time.Since(start), time.Minute, "a cancel ends the backoff")
	require.ErrorIs(t, err, context.Canceled)
	require.ErrorIs(t, err, attemptErr)
}
